import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"Interactive Campaign Gantt Timeline, Partner Cooperation, Request Validation & Campaign Closure","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/03-campaign-package-delivery/campaign-timeline-and-closure/spec.md","filePath":"feature/modules/03-campaign-package-delivery/campaign-timeline-and-closure/spec.md"}'),n={name:"feature/modules/03-campaign-package-delivery/campaign-timeline-and-closure/spec.md"};function r(c,e,s,l,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="interactive-campaign-gantt-timeline-partner-cooperation-request-validation-campaign-closure" tabindex="-1">Interactive Campaign Gantt Timeline, Partner Cooperation, Request Validation &amp; Campaign Closure <a class="header-anchor" href="#interactive-campaign-gantt-timeline-partner-cooperation-request-validation-campaign-closure" aria-label="Permalink to &quot;Interactive Campaign Gantt Timeline, Partner Cooperation, Request Validation &amp; Campaign Closure&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>campaign-timeline-and-closure</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>03-campaign-package-delivery</code> — Media Package Sharing, Campaign Timeline &amp; Delivery Closure</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>campaign-timeline</code>, <code>campaign-collaborators</code>, <code>campaign-task-ux</code>, <code>campaign-navigation-corrections</code>, <code>campaign-closure</code>, <code>request-completion-validation</code>, <code>workspace-campaign-summary</code>, <code>ui-refresh</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/04-media-package-campaign/README.html">3.5 Media Package &amp; Media Campaign</a> (<code>3.5.5–3.5.13</code>) · <a href="./../../../srs/06-ai-features/3-7-15-view-collaborator-directory/spec.html">FR 3.7.15 Collaborator Directory</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Unify active Campaign execution across the interactive <strong>Gantt &amp; Table Timeline</strong> (<code>CampaignTimelineController</code>), per-Campaign third-party <strong>Collaborator cooperation tracking</strong> (<code>CampaignCollaboratorController</code> — <code>DA-950</code>), <strong>Content Request completion validation</strong>, Workspace Campaign summary cards, and <strong>Campaign Closure</strong> (<code>CampaignClosureController</code>) with out-of-scope / supplemental Request Task accounting.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Manager</code> or <code>Owner</code>, I want to schedule, reorder, and color-code Campaign Tasks on an interactive Timeline, track linked third-party Collaborator cooperation states, validate all open Content Requests and deliverable Tasks before closing a Campaign, and cleanly cancel or carry over unfinished tasks upon closure.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Interactive Campaign Timeline (<code>campaign-timeline</code>, <code>campaign-task-ux</code>, <code>campaign-navigation-corrections</code>):</strong> <code>CampaignTimelineController</code> (<code>GET /campaigns/{campaignId}/timeline</code>, <code>PATCH /tasks/{taskId}/schedule</code>, <code>POST /timeline/tasks</code>, <code>PUT /timeline/reorder-tasks</code>) powers synchronized Gantt (<code>CampaignTimelineGrid.tsx</code>) and Table (<code>CampaignTimelineTableView.tsx</code>) views with unscheduled-task alerts (<code>TimelineUnscheduledRange.tsx</code>), milestone rails, assignee pickers, and color coding (<code>GanttColorPicker.tsx</code>).</li><li><strong>Campaign Collaborator Cooperation (<code>campaign-collaborators</code>, <code>DA-950</code>):</strong> <code>CampaignCollaboratorController</code> links active Agency partners (<code>third_party_collaborators</code>) into <code>campaign_collaborators</code> with independent per-Campaign <code>cooperation_status</code> (<code>PROPOSED</code>, <code>CONTACTED</code>, <code>CONFIRMED</code>, <code>DELIVERED</code>, <code>CANCELLED</code>), stamping <code>first_used_at</code> atomically and keeping historical links readable even if the partner is later deactivated.</li><li><strong>Content Request &amp; Campaign Completion Validation (<code>request-completion-validation</code>, <code>campaign-closure</code>):</strong> <code>GET /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/completion-check</code> inspects all package Tasks, supplemental Content Request Tasks (<code>content_requests</code>), and pending approvals. Closing a Campaign (<code>POST /campaigns/{campaignId}/complete</code>) requires resolving or explicitly cancelling (<code>POST /campaigns/{campaignId}/tasks/cancel</code>) open tasks with recorded audit reasons.</li><li><strong>Workspace Campaign Summary &amp; Scoped UI Polish (<code>workspace-campaign-summary</code>, <code>ui-refresh</code>):</strong> <code>WorkspaceCampaignSummary.tsx</code> displays real-time progress bars, milestone health, and deliverable completion counts on Workspace detail/dashboard views.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>campaign.{timeline,closure,partners,brief}.*</code>, <code>contentRequests.*</code> in <code>src/i18n/locales/{vi,en}/{campaign,contentRequests}.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/campaign/components/{CampaignTimelineGrid,CampaignTimelineTableView,CampaignClosureSection,CampaignMasterBriefCard,CampaignOutOfScopeTaskDialog}.tsx</code>, <code>pages/campaign-partners/page.tsx</code>, <code>WorkspaceCampaignSummary.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/CampaignsScreen.tsx</code>, <code>CampaignDetailScreen.tsx</code>, <code>ContentRequestsScreen.tsx</code>, <code>src/components/campaign/CampaignPartnersSection.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/timeline &amp; PATCH /tasks/{taskId}/schedule</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code> read; <code>Owner, Manager</code> write)</td><td style="text-align:left;"><code>CampaignTimelineController</code> -&gt; timeline projection &amp; drag-reschedule</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/campaign-collaborators &amp; POST /campaigns/{id}/collaborators</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>; <code>Client</code> read)</td><td style="text-align:left;"><code>CampaignCollaboratorController</code> -&gt; per-campaign partner linking &amp; status updates</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/campaigns/{campaignId}/completion-check &amp; POST /complete</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CampaignClosureController</code> &amp; <code>WorkspaceCampaignController</code> -&gt; pre-closure audit &amp; completion</td></tr><tr><td style="text-align:left;">`POST /api/v1/workspaces/{workspaceId}/content-requests/{requestId}/{receive</td><td style="text-align:left;">accept</td><td style="text-align:left;">deny}`</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Closing Campaign with Pending Client Request:</strong> Blocked (<code>409</code>) by <code>completion-check</code> until every <code>ContentRequestDocument</code> linked to the Campaign is completed, denied, or explicitly resolved.</li><li><strong>Task Scheduled Outside Campaign Window:</strong> Surfaces warning indicator on <code>TimelinePendingRange.tsx</code> / rejects invalid inverted start/end dates (<code>400</code>).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/04-media-package-campaign/README.html">3.5 Media Package &amp; Media Campaign</a> (<code>3.5.5–3.5.13</code>) · <a href="./../../../srs/06-ai-features/3-7-15-view-collaborator-directory/spec.html">FR 3.7.15 Collaborator Directory</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/04-media-package-campaign.html">BA 04 Media Package &amp; Campaign</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
